import csv
import io
from typing import Any, Dict, List


def parse_csv(raw_csv: str) -> Dict[str, List[Any]]:
    expected_width = 31
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = list(reader)

    header_index = None
    for index, record in enumerate(records):
        if record and any(value.strip() for value in record) and len(record) == expected_width:
            header_index = index
            break

    if header_index is None:
        for index, record in enumerate(records):
            if record and any(value.strip() for value in record):
                header_index = index
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    if len(columns) < expected_width:
        columns.extend(f"Column {index + 1}" for index in range(len(columns), expected_width))

    data_records = records[header_index + 1:]
    width = max([len(columns)] + [len(record) for record in data_records])

    while len(columns) < width:
        columns.append(f"Extra {len(columns) - expected_width + 1}")

    rows = []
    for record in data_records:
        row = list(record)
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
